import { dirname } from "node:path";
import { fileURLToPath } from "node:url";

import { FlatCompat } from "@eslint/eslintrc";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const compat = new FlatCompat({ baseDirectory: __dirname });

const eslintConfig = [
  {
    ignores: [
      ".next/**",
      "node_modules/**",
      "playwright-report/**",
      "test-results/**",
      // Generated by Next on every `dev` and `build`, and explicitly marked
      // "should not be edited". It carries a triple-slash reference by design,
      // so linting it reports a defect nobody can fix — the file would be
      // rewritten on the next run. Ignored here rather than disabled in place.
      "next-env.d.ts",
    ],
  },
  ...compat.extends("next/core-web-vitals", "next/typescript"),
  {
    rules: {
      // Content is authored in typed data files, so `any` is never needed.
      "@typescript-eslint/no-explicit-any": "error",
      "@typescript-eslint/consistent-type-imports": [
        "error",
        { prefer: "type-imports", fixStyle: "inline-type-imports" },
      ],
      // A leading underscore means "deliberately unused", which is a real idiom
      // in this codebase in two places: omitting a key before a rest spread
      // (`const { elapsedMs: _omitted, ...rest } = body`) and pulling a prop out
      // of an object only to keep it out of `...rest`. Neither is a mistake, so
      // neither should be reported. `ignoreRestSiblings` covers the cases that
      // exist today; the patterns cover the ones that will come up next.
      "@typescript-eslint/no-unused-vars": [
        "warn",
        {
          args: "after-used",
          argsIgnorePattern: "^_",
          varsIgnorePattern: "^_",
          caughtErrorsIgnorePattern: "^_",
          ignoreRestSiblings: true,
        },
      ],
    },
  },
];

export default eslintConfig;
